black_by={}
for chrom,s,e in black:
    black_by.setdefault(chrom,[]).append((s,e))
for chrom in black_by:
    black_by[chrom].sort()

intervals={}
count=0
with gzip.open('ENCFF333TAT.bed.gz','rt') as f:
    for line in f:
        p=line.rstrip('\\n').split('\\t')
        chrom=p[0]; start=int(p[1]); summit=int(p[9])
        center=start+summit
        s=center-250; e=center+250
        if s<0: s=0
        intervals.setdefault(chrom,[]).append((s,e))
        count+=1

def merge(lst):
    if not lst: return []
    lst.sort()
    out=[]
    cs,ce=lst[0]
    for s,e in lst[1:]:
        if s<=ce:
            if e>ce: ce=e
        else:
            out.append((cs,ce)); cs,ce=s,e
    out.append((cs,ce))
    return out

def remove_overlap(lst, blacklst):
    out=[]
    for s,e in lst:
        overlaps=False
        for bs,be in blacklst:
            if be <= s: continue
            if bs >= e: break
            if bs < e and be > s:
                overlaps=True; break
        if not overlaps:
